import{_ as a,o,c as l,ae as i}from"./chunks/framework.CK6jtcgr.js";const u=JSON.parse('{"title":"Agent Corps and Operational Roles","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent-corps-and-operational-roles.md","filePath":"guide/agent-corps-and-operational-roles.md"}'),t={name:"guide/agent-corps-and-operational-roles.md"};function r(n,e,s,d,p,c){return o(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="agent-corps-and-operational-roles" tabindex="-1">Agent Corps and Operational Roles <a class="header-anchor" href="#agent-corps-and-operational-roles" aria-label="Permalink to &quot;Agent Corps and Operational Roles&quot;">​</a></h1><p>SocioProphet uses a corps of narrowly-scoped operational roles rather than one unconstrained “AI that does everything.”</p><p>This is a public-safe summary of those roles.</p><h2 id="_1-public-role-model" tabindex="-1">1. Public role model <a class="header-anchor" href="#_1-public-role-model" aria-label="Permalink to &quot;1. Public role model&quot;">​</a></h2><p>The public-facing roles include:</p><ul><li>observer and profiler</li><li>egress and policy steward</li><li>safeguard and enforcement role</li><li>provenance and ledger role</li><li>simulation and validation role</li><li>evaluation and diffusion role</li><li>orchestration role</li><li>privacy and DLP role</li><li>bridge and diffusion controller</li></ul><h2 id="_2-why-role-separation-matters" tabindex="-1">2. Why role separation matters <a class="header-anchor" href="#_2-why-role-separation-matters" aria-label="Permalink to &quot;2. Why role separation matters&quot;">​</a></h2><p>Role separation reduces risk.</p><p>It prevents:</p><ul><li>one component from holding every privilege</li><li>hidden authority chains</li><li>unsafe coupling of detection, enforcement, and promotion</li><li>unreviewable automation drift</li></ul><h2 id="_3-what-the-corps-does-publicly" tabindex="-1">3. What the corps does publicly <a class="header-anchor" href="#_3-what-the-corps-does-publicly" aria-label="Permalink to &quot;3. What the corps does publicly&quot;">​</a></h2><p>Publicly, we document the corps in terms of:</p><ul><li>mission</li><li>scope</li><li>bounded capabilities</li><li>proof outputs</li><li>safety gates</li><li>operator handoff model</li></ul><h2 id="_4-what-we-do-not-publish-publicly" tabindex="-1">4. What we do not publish publicly <a class="header-anchor" href="#_4-what-we-do-not-publish-publicly" aria-label="Permalink to &quot;4. What we do not publish publicly&quot;">​</a></h2><p>We do not publish the full internal operator kit.</p><p>We do not publish:</p><ul><li>high-risk playbooks</li><li>sensitive enforcement internals</li><li>adversary-emulation mechanics</li><li>private thresholds</li><li>exploit or persistence methods</li><li>misuse-enabling tactical details</li></ul><h2 id="_5-relation-to-the-platform" tabindex="-1">5. Relation to the platform <a class="header-anchor" href="#_5-relation-to-the-platform" aria-label="Permalink to &quot;5. Relation to the platform&quot;">​</a></h2><p>The corps belongs inside the governed operational model described in:</p><ul><li><a href="./governed-ai-and-cybernetics">Governed AI and Cybernetics</a></li><li><a href="./agent-plane-and-operator-workflows">Agent Plane and Operator Workflows</a></li><li><a href="./authorized-cyberdefense-and-simulation">Authorized Cyberdefense and Simulation</a></li></ul><h2 id="_6-public-takeaway" tabindex="-1">6. Public takeaway <a class="header-anchor" href="#_6-public-takeaway" aria-label="Permalink to &quot;6. Public takeaway&quot;">​</a></h2><p>The point is not to build an army of opaque bots. The point is to create a disciplined, bounded, evidence-producing operational stack with clear roles, proofs, and review.</p>',22)])])}const b=a(t,[["render",r]]);export{u as __pageData,b as default};
